distNumBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "distNumBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "VarDistPlots",
                name = "distNum",
                version = c(0,4,0),
                options = options,
                results = distNumResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Comparison of Numeric Variables
#'
#' 
#' @param data .
#' @param vars .
#' @param orientation .
#' @param invertVars .
#' @param palette .
#' @param reversePalette .
#' @param theme .
#' @param textSize .
#' @param alpha .
#' @param lineWidth .
#' @param pointSize .
#' @param jitterSpread .
#' @param valueLabel .
#' @param title .
#' @param showN .
#' @param legendPos .
#' @param autoSize .
#' @param plotWidth .
#' @param plotHeight .
#' @param showBox .
#' @param boxWidth .
#' @param boxOutliers .
#' @param boxNotch .
#' @param boxMean .
#' @param boxJitter .
#' @param showViolin .
#' @param violinWidth .
#' @param violinScale .
#' @param violinAdjust .
#' @param violinTrim .
#' @param violinInner .
#' @param violinJitter .
#' @param showErrorBar .
#' @param ebCenter .
#' @param ebInterval .
#' @param ebLevel .
#' @param ebMult .
#' @param ebJitter .
#' @param ebSize .
#' @param ebCap .
#' @param ebConnect .
#' @param ebLabels .
#' @param showRaincloud .
#' @param rcCloudWidth .
#' @param rcAdjust .
#' @param rcRain .
#' @param rcBox .
#' @param showRidge .
#' @param ridgeOverlap .
#' @param ridgeAdjust .
#' @param ridgeTrim .
#' @param ridgeMedian .
#' @param showHist .
#' @param histBins .
#' @param histStat .
#' @param histDensity .
#' @param histFreeY .
#' @param showDensity .
#' @param densAdjust .
#' @param densFilled .
#' @param densTrim .
#' @param showEcdf .
#' @param ecdfMedian .
#' @param showStrip .
#' @param stripSummary .
#' @param showBarcode .
#' @param barcodeHeight .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$hint} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot_box} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_violin} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_errorbar} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_raincloud} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_ridge} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_hist} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_density} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_ecdf} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_strip} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_barcode} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' @export
distNum <- function(
    data,
    vars,
    orientation = "horizontal",
    invertVars = FALSE,
    palette = "viridis",
    reversePalette = FALSE,
    theme = "minimal",
    textSize = 12,
    alpha = 80,
    lineWidth = 2,
    pointSize = 1.4,
    jitterSpread = 40,
    valueLabel = "Value",
    title = "",
    showN = TRUE,
    legendPos = "bottom",
    autoSize = TRUE,
    plotWidth = 700,
    plotHeight = 480,
    showBox = TRUE,
    boxWidth = 60,
    boxOutliers = TRUE,
    boxNotch = FALSE,
    boxMean = FALSE,
    boxJitter = FALSE,
    showViolin = FALSE,
    violinWidth = 80,
    violinScale = "area",
    violinAdjust = 1,
    violinTrim = TRUE,
    violinInner = "box",
    violinJitter = FALSE,
    showErrorBar = FALSE,
    ebCenter = "mean",
    ebInterval = "ci",
    ebLevel = 95,
    ebMult = 1,
    ebJitter = TRUE,
    ebSize = 3.5,
    ebCap = 30,
    ebConnect = FALSE,
    ebLabels = FALSE,
    showRaincloud = FALSE,
    rcCloudWidth = 45,
    rcAdjust = 1,
    rcRain = TRUE,
    rcBox = TRUE,
    showRidge = FALSE,
    ridgeOverlap = 50,
    ridgeAdjust = 1,
    ridgeTrim = FALSE,
    ridgeMedian = FALSE,
    showHist = FALSE,
    histBins = 20,
    histStat = "count",
    histDensity = FALSE,
    histFreeY = FALSE,
    showDensity = FALSE,
    densAdjust = 1,
    densFilled = TRUE,
    densTrim = FALSE,
    showEcdf = FALSE,
    ecdfMedian = TRUE,
    showStrip = FALSE,
    stripSummary = "none",
    showBarcode = FALSE,
    barcodeHeight = 70) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("distNum requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- distNumOptions$new(
        vars = vars,
        orientation = orientation,
        invertVars = invertVars,
        palette = palette,
        reversePalette = reversePalette,
        theme = theme,
        textSize = textSize,
        alpha = alpha,
        lineWidth = lineWidth,
        pointSize = pointSize,
        jitterSpread = jitterSpread,
        valueLabel = valueLabel,
        title = title,
        showN = showN,
        legendPos = legendPos,
        autoSize = autoSize,
        plotWidth = plotWidth,
        plotHeight = plotHeight,
        showBox = showBox,
        boxWidth = boxWidth,
        boxOutliers = boxOutliers,
        boxNotch = boxNotch,
        boxMean = boxMean,
        boxJitter = boxJitter,
        showViolin = showViolin,
        violinWidth = violinWidth,
        violinScale = violinScale,
        violinAdjust = violinAdjust,
        violinTrim = violinTrim,
        violinInner = violinInner,
        violinJitter = violinJitter,
        showErrorBar = showErrorBar,
        ebCenter = ebCenter,
        ebInterval = ebInterval,
        ebLevel = ebLevel,
        ebMult = ebMult,
        ebJitter = ebJitter,
        ebSize = ebSize,
        ebCap = ebCap,
        ebConnect = ebConnect,
        ebLabels = ebLabels,
        showRaincloud = showRaincloud,
        rcCloudWidth = rcCloudWidth,
        rcAdjust = rcAdjust,
        rcRain = rcRain,
        rcBox = rcBox,
        showRidge = showRidge,
        ridgeOverlap = ridgeOverlap,
        ridgeAdjust = ridgeAdjust,
        ridgeTrim = ridgeTrim,
        ridgeMedian = ridgeMedian,
        showHist = showHist,
        histBins = histBins,
        histStat = histStat,
        histDensity = histDensity,
        histFreeY = histFreeY,
        showDensity = showDensity,
        densAdjust = densAdjust,
        densFilled = densFilled,
        densTrim = densTrim,
        showEcdf = showEcdf,
        ecdfMedian = ecdfMedian,
        showStrip = showStrip,
        stripSummary = stripSummary,
        showBarcode = showBarcode,
        barcodeHeight = barcodeHeight)

    analysis <- distNumClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

